import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.CYjxsSA2.js";const g=JSON.parse('{"title":"消息通知","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/notify.md","filePath":"advanced/notify.md"}'),n={name:"advanced/notify.md"};function l(i,t,d,s,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="消息通知" tabindex="-1">消息通知 <a class="header-anchor" href="#消息通知" aria-label="Permalink to &quot;消息通知&quot;">​</a></h1><p>消息通知把作业进展与漏洞告警推送到<strong>飞书 / 企业微信</strong>群机器人，适合团队协作与值班值守。</p><h2 id="推送什么" tabindex="-1">推送什么 <a class="header-anchor" href="#推送什么" aria-label="Permalink to &quot;推送什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>内容</th></tr></thead><tbody><tr><td><strong>漏洞告警</strong></td><td>新发现的漏洞条目，按严重级别着色</td></tr><tr><td><strong>任务汇总</strong></td><td>军团会话结束后的总结，按站点分组</td></tr></tbody></table><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p><strong>系统配置 → 消息通知</strong>：</p><ol><li>新建<strong>通知组</strong>，组内添加一个或多个 Webhook</li><li>每个 Webhook 选择平台（飞书 / 企业微信），填完整地址或只填 token / key</li><li>设置<strong>推送阈值</strong>：达到指定严重级别才推送</li><li>在项目里可指定使用哪些通知组；未指定时推送到全部已启用组</li></ol><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li><strong>开关必须打开</strong>：只在设置里填了 Webhook 但没启用，不会推送</li><li>企业微信单条消息有长度上限，超出会被整条拒收，因此汇总会<strong>拆成多条</strong>发送，属正常行为</li><li>飞书汇总卡片有展开上限，超出部分会显式标注「以及其他 N 个」，完整清单请到<a href="/vaelor/guide/vulnreports.html">漏洞管理</a>查看</li><li>收不到消息时，依次检查：开关、推送阈值、机器人是否被群管理风控</li></ul><h2 id="测试" tabindex="-1">测试 <a class="header-anchor" href="#测试" aria-label="Permalink to &quot;测试&quot;">​</a></h2><p>通知组里的每个 Webhook 都可以单独<strong>发送测试消息</strong>，先确认链路通再接真实推送。</p>',11)])])}const b=a(n,[["render",l]]);export{g as __pageData,b as default};
